import org.pantryrecipes.app.core.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
/** v2.2: writes js/data22.js (illustration glyphs, from assets/illustrations.txt) and tests/vectors22b.json (glyph per recipe, sources, parsers). */
public class V22Export {
    static String q(String s) { return Json.write(s); }
    public static void main(String[] a) throws Exception {
        File app = new File(a[0]), web = new File(a[1]);
        String ill = new String(Files.readAllBytes(new File(app, "assets/illustrations.txt").toPath()), StandardCharsets.UTF_8);
        Files.write(new File(web, "js/data22.js").toPath(), ("/* generated by tools/V22Export.java from assets/illustrations.txt */\nself.PR_DATA22 = { illustrations: " + q(ill) + " };\n").getBytes(StandardCharsets.UTF_8));
        List<Recipe> rs = Recipe.parseList(new String(Files.readAllBytes(new File(app, "assets/recipes.json").toPath()), StandardCharsets.UTF_8));
        StringBuilder g = new StringBuilder(), k = new StringBuilder();
        Map<String, Integer> count = new TreeMap<String, Integer>();
        for (Recipe r : rs) { String x = Illustration.glyph(r); g.append(g.length() > 0 ? "," : "").append(x); count.merge(x, 1, Integer::sum); }
        Set<String> cz = new TreeSet<String>(); for (Recipe r : rs) cz.add(r.cuisine);
        for (String c : cz) k.append(k.length() > 0 ? ";" : "").append(c).append("=").append(Integer.toHexString(Illustration.accent(c))).append("/").append(Illustration.pattern(c));
        StringBuilder o = new StringBuilder("{\n\"glyphs\":").append(q(g.toString())).append(",\n\"looks\":").append(q(k.toString())).append(",\n\"links\":[");
        String[] qs = {"chicken curry", "Pão de queijo", "mac & cheese"};
        int n = 0;
        for (String[] l : Sources.LINKS) for (String s : qs) o.append(n++ > 0 ? "," : "").append("[").append(q(l[0])).append(",").append(q(s)).append(",").append(q(Sources.linkUrl(l[0], s))).append("]");
        o.append("],\n\"wbApi\":").append(q(Sources.wikibooksApi("chicken curry"))).append(",\n\"ovApi\":").append(q(Sources.openverseApi("Pão de queijo")));
        String wb = "{\"query\":{\"search\":[{\"ns\":102,\"title\":\"Cookbook:Chicken Curry\",\"snippet\":\"| <span class=\\\"searchmatch\\\">Curry</span> &amp; rice\"},{\"title\":\"Talk:x\",\"snippet\":\"\"},{\"title\":\"Cookbook:Kari Ayam (Indonesian Chicken Curry)\",\"snippet\":\"Kari\"}]}}";
        StringBuilder wo = new StringBuilder(); for (Sources.Hit h : Sources.parseWikibooks(wb)) wo.append(wo.length() > 0 ? "\n" : "").append(h.title).append("|").append(h.snippet).append("|").append(h.url);
        String ov = "{\"results\":[{\"title\":\"Chicken Curry\",\"url\":\"https://live.staticflickr.com/1.jpg\",\"thumbnail\":\"https://api.openverse.org/v1/images/x/thumb/\",\"creator\":\"rovingI\",\"license\":\"by\",\"license_version\":\"2.0\",\"foreign_landing_url\":\"https://www.flickr.com/photos/1\",\"provider\":\"flickr\"},{\"title\":\"nc\",\"url\":\"https://a/b.jpg\",\"license\":\"by-nc\"},{\"title\":\"\",\"url\":\"http://insecure/x.jpg\",\"license\":\"cc0\"},{\"title\":\" \",\"url\":\"https://c/d.jpg\",\"license\":\"pdm\",\"creator\":\"\",\"provider\":\"wikimedia\"}]}";
        StringBuilder po = new StringBuilder(); for (Sources.Photo p : Sources.parseOpenverse(ov)) po.append(po.length() > 0 ? "\n" : "").append(p.thumb).append("|").append(p.credit()).append("|").append(p.encode());
        o.append(",\n\"wbIn\":").append(q(wb)).append(",\n\"wbOut\":").append(q(wo.toString())).append(",\n\"ovIn\":").append(q(ov)).append(",\n\"ovOut\":").append(q(po.toString())).append("\n}\n");
        Files.write(new File(web, "tests/vectors22b.json").toPath(), o.toString().getBytes(StandardCharsets.UTF_8));
        System.out.println("V22Export: data22.js " + new File(web, "js/data22.js").length() + " bytes; glyphs " + count);
    }
}
